fn solve(n: i8, m: i8) -> (i8, i8) {
    // We assume n >= 1 and m >= 1.
    // Let `second` be the smaller of the two inputs,
    // and `first` = (larger input) - 1.
    let second = n.min(m);
    let first = n.max(m) - 1;
    (first, second)
}

